statements:
create table if not exists public.dp_pyq_v1_production_release (
  question_id text primary key references public.questions(question_id) on delete cascade,
  release_version text not null,
  production_eligible boolean not null default false,
  intelligence_eligible boolean not null default false,
  human_review_required boolean not null default true,
  promoted_at timestamptz not null default now(),
  constraint dp_pyq_v1_production_release_version_check
    check (release_version = 'DP_PYQ_CORPUS_v1')
);

create index if not exists idx_dp_pyq_v1_production_release_intelligence
  on public.dp_pyq_v1_production_release (intelligence_eligible);

create index if not exists idx_dp_pyq_v1_production_release_review
  on public.dp_pyq_v1_production_release (human_review_required);

alter table public.dp_pyq_v1_production_release enable row level security;
revoke all on public.dp_pyq_v1_production_release from anon, authenticated;

comment on table public.dp_pyq_v1_production_release is
'Materialized production promotion contract for DP_PYQ_CORPUS_v1. Eligibility is promoted from the frozen intelligence-lab release; application code must not recompute release eligibility.';

create table if not exists public.dp_question_intelligence_v1 (
  question_id text primary key references public.questions(question_id) on delete cascade,
  taxonomy_subject text not null,
  taxonomy_topic text not null,
  taxonomy_subtopic text not null,
  taxonomy_concept text not null,
  competency_id text not null,
  pattern_id text not null,
  source_id text not null,
  temporal_context_id text not null,
  expected_knowledge numeric,
  source_accessibility numeric,
  preparation_accessibility numeric,
  cognitive_complexity numeric,
  esac_score numeric,
  difficulty_score numeric,
  difficulty_category text not null check (difficulty_category in ('Easy','Moderate','Hard')),
  relation_degree bigint not null default 0,
  same_concept_degree bigint not null default 0,
  cross_exam_variant_degree bigint not null default 0,
  conceptual_variant_degree bigint not null default 0,
  intelligence_readiness text,
  requires_content_review boolean not null default false,
  release_eligible boolean not null default false,
  production_eligible boolean not null default true,
  intelligence_eligible boolean not null default false,
  human_review_required boolean not null default true,
  release_version text not null default 'DP_PYQ_CORPUS_v1',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_dp_qi_v1_subject on public.dp_question_intelligence_v1(taxonomy_subject);
create index if not exists idx_dp_qi_v1_topic on public.dp_question_intelligence_v1(taxonomy_subject, taxonomy_topic);
create index if not exists idx_dp_qi_v1_subtopic on public.dp_question_intelligence_v1(taxonomy_subject, taxonomy_topic, taxonomy_subtopic);
create index if not exists idx_dp_qi_v1_competency on public.dp_question_intelligence_v1(competency_id);
create index if not exists idx_dp_qi_v1_pattern on public.dp_question_intelligence_v1(pattern_id);
create index if not exists idx_dp_qi_v1_source on public.dp_question_intelligence_v1(source_id);
create index if not exists idx_dp_qi_v1_temporal on public.dp_question_intelligence_v1(temporal_context_id);
create index if not exists idx_dp_qi_v1_intelligence_eligible on public.dp_question_intelligence_v1(intelligence_eligible);
create index if not exists idx_dp_qi_v1_exam_filters on public.dp_question_intelligence_v1(question_id, difficulty_category);

alter table public.dp_question_intelligence_v1 enable row level security;
revoke all on public.dp_question_intelligence_v1 from anon, authenticated;
grant select, insert, update, delete on public.dp_question_intelligence_v1 to service_role;

comment on table public.dp_question_intelligence_v1 is
'Production snapshot of DP_PYQ_CORPUS_v1 intelligence. Intelligence Lab is the derivation factory; this table is the production read model. Eligibility flags are imported from the frozen release and must not be recomputed independently in application code.';

alter table public.dp_question_intelligence_v1
add column if not exists intelligence_confidence text not null default 'MODEL_DERIVED',
add column if not exists intelligence_verified boolean not null default false,
add column if not exists human_review_required boolean not null default true;

create index if not exists idx_dp_qi_v1_review on public.dp_question_intelligence_v1(human_review_required, intelligence_verified);

comment on column public.dp_question_intelligence_v1.intelligence_confidence is
'Provenance state of derived intelligence. MODEL_DERIVED means generated from the frozen structured release but not independently human-verified.';
comment on column public.dp_question_intelligence_v1.intelligence_verified is
'Whether the intelligence fields have passed human verification. This is distinct from intelligence eligibility.';

create or replace function public.validate_question_taxonomy_contract()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if new.subtopic ~ '^\s*\d+(\.\d+)+\s+' then
    raise exception 'Legacy numbered subtopic is not allowed: %', new.subtopic;
  end if;
  if new.theme ~ '^\s*\d+(\.\d+)+\s+' then
    raise exception 'Legacy numbered theme is not allowed: %', new.theme;
  end if;
  if new.q_pattern is not null and btrim(new.q_pattern) <> '' and not exists (
    select 1 from public.dp_pattern_dictionary d
    where d.display_label = btrim(new.q_pattern) and d.active
  ) then
    raise exception 'Invalid q_pattern display label: %', new.q_pattern;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_validate_question_taxonomy_contract on public.questions;
create trigger trg_validate_question_taxonomy_contract
before insert or update of subtopic, theme, q_pattern
on public.questions
for each row execute function public.validate_question_taxonomy_contract();

create index if not exists idx_dp_pattern_dictionary_active
on public.dp_pattern_dictionary(active, pattern_id);
